<?php
require_once 'config.php';require_login();$pdo=db();$page_title='Remittance';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$agent=(int)($_POST['agent_id']??0);$amount=(float)($_POST['amount']??0);$date=$_POST['remittance_date']??date('Y-m-d');if($agent<1||$amount<=0)throw new RuntimeException('Choose an agent and enter an amount greater than zero.');$stmt=$pdo->prepare('INSERT INTO remittances(agent_id,amount,remittance_date,reference_no,notes) VALUES(?,?,?,?,?)');$stmt->execute([$agent,$amount,$date,trim($_POST['reference_no']??''),trim($_POST['notes']??'')]);redirect('remittance.php');}catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'Unable to record remittance.';}}
$agents=$pdo->query("SELECT a.id,a.name,COALESCE((SELECT SUM(d.package_kg*d.quantity*d.price_per_kg) FROM deliveries d WHERE d.agent_id=a.id AND d.status='Delivered'),0) AS sales,COALESCE((SELECT SUM(r.amount) FROM remittances r WHERE r.agent_id=a.id),0) AS paid FROM agents a ORDER BY a.name")->fetchAll();
$rows=$pdo->query("SELECT r.*,a.name AS agent_name FROM remittances r JOIN agents a ON a.id=r.agent_id ORDER BY r.remittance_date DESC,r.id DESC")->fetchAll();
$paid=0;foreach($rows as $r)$paid+=(float)$r['amount'];$salesTotal=0;foreach($agents as $a)$salesTotal+=(float)$a['sales'];
require 'includes/header.php';?><div class="shell"><?php require 'includes/sidebar.php';?><main class="main"><?php require 'includes/topbar.php';?><div class="content"><div class="page-heading"><div><div class="eyebrow">PAYMENT TRACKING</div><h1>Remittance</h1><p>Record money returned by agents and monitor the estimated amount due.</p></div></div><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?>
<div class="cards"><div class="stat"><div class="stat-top">Delivered sales <span class="stat-icon">₱</span></div><strong><?=money($salesTotal)?></strong><small>Delivered sales across all agents</small></div><div class="stat"><div class="stat-top">Remittance received <span class="stat-icon">⇄</span></div><strong><?=money($paid)?></strong><small>All recorded payments</small></div><div class="stat"><div class="stat-top">Estimated balance due <span class="stat-icon">◷</span></div><strong><?=money($salesTotal-$paid)?></strong><small>Sales less remittances; verify agent agreements</small></div></div>
<div class="panel"><div class="panel-head"><h2>Record remittance</h2></div><div class="panel-body"><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Agent *</label><select name="agent_id" required><option value="">Choose agent</option><?php foreach($agents as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Amount received (₱) *</label><input type="number" name="amount" min="0.01" step="0.01" required></div><div class="field"><label>Date received *</label><input type="date" name="remittance_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Reference number</label><input name="reference_no" maxlength="100" placeholder="Receipt or transaction ID"></div><div class="field full"><label>Notes</label><input name="notes" maxlength="255"></div><div class="field full"><button class="btn">＋ Save remittance</button></div></form></div></div>
<div class="panel"><div class="panel-head"><h2>Agent balances</h2></div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Delivered sales</th><th>Paid</th><th>Estimated due</th></tr></thead><tbody><?php if(!$agents):?><tr><td colspan="4" class="empty">Add agents and deliveries first.</td></tr><?php endif;?><?php foreach($agents as $a):$due=(float)$a['sales']-(float)$a['paid'];?><tr><td><?=e($a['name'])?></td><td><?=money($a['sales'])?></td><td><?=money($a['paid'])?></td><td><strong><?=money($due)?></strong></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="panel"><div class="panel-head"><h2>Remittance history</h2></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Agent</th><th>Amount</th><th>Reference</th><th>Notes</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">No remittances recorded.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['remittance_date'])?></td><td><?=e($r['agent_name'])?></td><td><strong><?=money($r['amount'])?></strong></td><td><?=e($r['reference_no']?:'—')?></td><td><?=e($r['notes']?:'—')?></td></tr><?php endforeach;?></tbody></table></div></div>
<p class="help">Accounting note: this starter version estimates agent balances as delivered sales minus recorded remittances. If your agents use different pricing, credit, returned-ice, or remittance rules, confirm those rules before using the figures for official accounting.</p>
</div><?php require 'includes/footer.php';?></main></div>
